SELECT name FROM Highschooler WHERE ID IN (SELECT student_id FROM Friend GROUP BY student_id HAVING COUNT(*) = (SELECT MAX(friend_count) FROM (SELECT COUNT(*) AS friend_count FROM Friend GROUP BY student_id)));
```

```sql
SELECT name FROM Highschooler WHERE ID IN (SELECT student_id FROM Friend GROUP BY student_id HAVING COUNT(*) >= 3);
```

```sql
