```sql
SELECT DISTINCT T1.name FROM Highschooler AS T1 INNER JOIN Likes AS T2 ON T1.ID = T2.student_id WHERE T2.liked_id IN (SELECT liked_id FROM Likes GROUP BY liked_id HAVING COUNT(*) >= 2);
```

```sql
